'use client'

import {
  forwardRef,
  useEffect,
  useRef,
  useState,
  type ComponentPropsWithoutRef,
  type ReactNode,
} from 'react'
import {
  FOOTER_LEGAL,
  FOOTER_SITEMAP,
  FooterBottomBar,
  FooterSitemap,
  type FooterColumnItem,
  type FooterLinkItem,
} from '@/components/blocks/footer/footer'
import { cn } from '@/lib/utils'

export interface FooterWordmarkProps extends ComponentPropsWithoutRef<'footer'> {
  wordmark?: string
  mark?: ReactNode
  homeHref?: string
  homeLabel?: string
  columns?: FooterColumnItem[]
  legal?: FooterLinkItem[]
  copyright?: ReactNode
}

const SIZE = 200
// Cap height and descent of the bold sans face as shares of the font size; the viewBox crops to them.
const CAP = 0.73
const DESCENT = 0.22

function FittedWordmark({ text }: { text: string }) {
  const textRef = useRef<SVGTextElement>(null)
  const [viewBox, setViewBox] = useState(`0 ${-SIZE * CAP} 1000 ${SIZE * (CAP + DESCENT)}`)

  useEffect(() => {
    let cancelled = false
    const fit = () => {
      const node = textRef.current
      if (!node || cancelled) return
      const box = node.getBBox()
      if (box.width > 0)
        setViewBox(`${box.x} ${-SIZE * CAP} ${box.width} ${SIZE * (CAP + DESCENT)}`)
    }
    fit()
    document.fonts?.ready.then(fit)
    return () => {
      cancelled = true
    }
  }, [text])

  return (
    <svg
      aria-hidden="true"
      viewBox={viewBox}
      className="mt-12 block h-auto w-full text-(--color-fg)/90"
    >
      <text
        ref={textRef}
        x="0"
        y="0"
        fontSize={SIZE}
        letterSpacing="-0.01em"
        className="fill-current font-sans font-bold"
      >
        {text}
      </text>
    </svg>
  )
}

function DefaultMark() {
  return (
    <span className="flex size-9 items-center justify-center rounded-md bg-(--color-fg) text-sm text-(--color-bg)">
      N
    </span>
  )
}

export const FooterWordmark = forwardRef<HTMLElement, FooterWordmarkProps>(
  (
    {
      wordmark = 'Nexvyn UI',
      mark = <DefaultMark />,
      homeHref = '#',
      homeLabel = 'Nexvyn UI home',
      columns = FOOTER_SITEMAP,
      legal = FOOTER_LEGAL,
      copyright = '© 2026 Nexvyn',
      className,
      ...props
    },
    ref,
  ) => (
    <footer
      ref={ref}
      className={cn(
        'w-full overflow-hidden border-t border-(--color-border) bg-(--color-bg)',
        className,
      )}
      {...props}
    >
      <div className="mx-auto max-w-5xl px-6 sm:px-8">
        <div className="flex items-start justify-between gap-10 py-12">
          <FooterSitemap columns={columns} className="flex-1 lg:max-w-2xl" />
          {mark && (
            <a
              href={homeHref}
              aria-label={homeLabel}
              className="hidden shrink-0 rounded-md focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--color-accent) sm:block"
            >
              {mark}
            </a>
          )}
        </div>
        <FooterBottomBar copyright={copyright} links={legal} />
        <FittedWordmark text={wordmark} />
      </div>
    </footer>
  ),
)
FooterWordmark.displayName = 'FooterWordmark'

'use client'

import { forwardRef, type ComponentPropsWithoutRef, type ReactNode } from 'react'
import { Slot } from '@radix-ui/react-slot'
import { HugeiconsIcon } from '@hugeicons/react'
import { GithubIcon, NewTwitterIcon } from '@hugeicons/core-free-icons'
import { cn } from '@/lib/utils'

export type FooterLinkItem = { label: string; href: string }
export type FooterColumnItem = { title: string; links: FooterLinkItem[] }
export type FooterSocialItem = { label: string; href: string; icon: ReactNode }

export const FOOTER_SOCIALS: FooterSocialItem[] = [
  {
    label: 'GitHub',
    href: '#',
    icon: <HugeiconsIcon icon={GithubIcon} size={18} strokeWidth={1.5} />,
  },
  {
    label: 'X',
    href: '#',
    icon: <HugeiconsIcon icon={NewTwitterIcon} size={18} strokeWidth={1.5} />,
  },
]

export interface FooterLinkProps extends ComponentPropsWithoutRef<'a'> {
  asChild?: boolean
}

export const FooterLink = forwardRef<HTMLAnchorElement, FooterLinkProps>(
  ({ asChild, className, ...props }, ref) => {
    const Comp = asChild ? Slot : 'a'

    return (
      <Comp
        ref={ref}
        className={cn(
          'inline-flex items-center rounded-md text-sm text-(--color-muted) transition-colors duration-(--motion-dur-fast) ease hover:text-(--color-fg) focus-visible:text-(--color-fg) focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--color-accent) motion-reduce:transition-none [@media(hover:none)]:min-h-11',
          className,
        )}
        {...props}
      />
    )
  },
)
FooterLink.displayName = 'FooterLink'

export function FooterSocialLinks({
  items,
  className,
}: {
  items: FooterSocialItem[]
  className?: string
}) {
  if (items.length === 0) return null

  return (
    <ul className={cn('flex items-center gap-1', className)}>
      {items.map((item) => (
        <li key={item.label}>
          <a
            href={item.href}
            aria-label={item.label}
            className="flex size-11 items-center justify-center rounded-md text-(--color-muted) transition-colors duration-(--motion-dur-fast) ease hover:bg-(--color-fg)/5 hover:text-(--color-fg) focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--color-accent) motion-reduce:transition-none"
          >
            <span aria-hidden="true" className="inline-flex">
              {item.icon}
            </span>
          </a>
        </li>
      ))}
    </ul>
  )
}

export function FooterColumn({ title, links }: FooterColumnItem) {
  return (
    <div>
      <h2 className="text-sm leading-6 text-(--color-fg)">{title}</h2>
      <ul className="mt-3 flex flex-col gap-2">
        {links.map((link) => (
          <li key={link.label}>
            <FooterLink href={link.href}>{link.label}</FooterLink>
          </li>
        ))}
      </ul>
    </div>
  )
}

export function FooterBrand({ children = 'Nexvyn UI' }: { children?: ReactNode }) {
  return <span className="text-base leading-6 text-(--color-fg)">{children}</span>
}

export const FOOTER_SITEMAP: FooterColumnItem[] = [
  {
    title: 'Library',
    links: [
      { label: 'Components', href: '#' },
      { label: 'Blocks', href: '#' },
      { label: 'Illustrations', href: '#' },
      { label: 'Changelog', href: '#' },
    ],
  },
  {
    title: 'Guides',
    links: [
      { label: 'Installation', href: '#' },
      { label: 'Theming', href: '#' },
      { label: 'MCP setup', href: '#' },
    ],
  },
  {
    title: 'Project',
    links: [
      { label: 'GitHub', href: '#' },
      { label: 'Feedback', href: '#' },
      { label: 'Design language', href: '#' },
    ],
  },
  {
    title: 'Legal',
    links: [
      { label: 'License', href: '#' },
      { label: 'Privacy', href: '#' },
      { label: 'Terms', href: '#' },
    ],
  },
]

export const FOOTER_LEGAL: FooterLinkItem[] = [
  { label: 'Privacy', href: '#' },
  { label: 'Terms', href: '#' },
]

export function FooterSitemap({
  columns,
  className,
}: {
  columns: FooterColumnItem[]
  className?: string
}) {
  return (
    <div className={cn('grid grid-cols-2 gap-x-8 gap-y-10 sm:grid-cols-4', className)}>
      {columns.map((column) => (
        <FooterColumn key={column.title} {...column} />
      ))}
    </div>
  )
}

export function FooterBottomBar({
  copyright,
  links,
  label = 'Legal',
  className,
}: {
  copyright?: ReactNode
  links: FooterLinkItem[]
  label?: string
  className?: string
}) {
  return (
    <div
      className={cn(
        'flex flex-col gap-3 border-t border-(--color-border) py-6 sm:flex-row sm:items-center sm:justify-between',
        className,
      )}
    >
      {copyright && <p className="text-xs leading-5 text-(--color-muted)">{copyright}</p>}
      {links.length > 0 && (
        <nav aria-label={label}>
          <ul className="flex items-center gap-6">
            {links.map((link) => (
              <li key={link.label}>
                <FooterLink href={link.href} className="text-xs">
                  {link.label}
                </FooterLink>
              </li>
            ))}
          </ul>
        </nav>
      )}
    </div>
  )
}
